(()=>{for(const button of document.querySelectorAll('[data-new-game]'))button.addEventListener('click',async()=>{window.dispatchEvent(new Event('game:new-game'));window.Craft?.cancelAnalysis?.();button.disabled=true;button.setAttribute('aria-busy','true');button.lastChild.textContent=' 초기화 중…';await Promise.allSettled([window.Craft?.EffectJobs?.reset(),fetch('/api/evolution/reset',{method:'POST',signal:AbortSignal.timeout(10000)})]);window.BattleSave?.clear(location.hash);try{window.Craft?.StorageCleanup?.collect({reset:true});}catch(error){console.error(error.message);}location.replace('start.html?newGame='+Date.now());});})();
